		const idx = (k % n + n) % n;
		const perm = orders[idx];
		const prev = orders[(idx + n - 1) % n];
		const u = smooth((t - from) / .7);
		balls.forEach((ball, i) => {
			const x = slots[prev[i]] + (slots[perm[i]] - slots[prev[i]]) * u;
			ball.position.set(x, -.35, 0);
		});
		show(captions, idx);
