	cap.position.set(gold.position.x + .7, gold.position.y, .1);
	const lo = label(THREE, "0", .45);
	const hi = label(THREE, "1", .45);
	lo.position.set(-1.85, -1.05, 0);
	hi.position.set(-1.85, .85, 0);
	world.add(gold, cap, lo, hi);
