			const dot = new THREE.Mesh(new THREE.SphereGeometry(.045, 8, 8), lambert(THREE, k === 1 ? GOLD : CREAM));
			dot.position.set(x0 + (i - 3) * .12, -.7 + p * 1.2, 0);
